        observe: "Share of conversations answered within the window, messages failed due to closed windows, template use for re-engagement, and time to first response.",
        security: "Authenticate agents, log who sent what in each window, and avoid sharing sensitive data in free-form messages without verification.",
        checklist: ['Last inbound timestamp stored from webhooks', 'Server-side window computation', 'Agent countdown', 'Send-time window re-check', 'Follow-up templates prepared', 'Bot-to-human handover with time left', 'Response-time targets under 24 hours'],
        sources: ['Meta for Developers: Customer service windows and pricing (accessed October 2026)', 'Meta for Developers: Free entry point windows', 'Meta for Developers: Cloud API message types'],
