      ex: { prompt: 'Write nextTier(current, maxUsed7d, quality) with tiers [250, 2000, 10000, 100000, -1] (-1 = unlimited). If current is not a tier, is -1, or quality is "low", return current. Otherwise return the next tier if maxUsed7d ≥ current / 2, else current.', fn: 'nextTier', params: 'current, maxUsed7d, quality', cases: [{ args: [250, 200, 'high'], expect: 2000 }, { args: [2000, 500, 'high'], expect: 2000 }, { args: [10000, 6000, 'low'], expect: 10000 }, { args: [100000, 60000, 'medium'], expect: -1 }, { args: [-1, 1, 'high'], expect: -1 }], solution: `function nextTier(c,u,q){const t=[250,2000,10000,100000,-1];const i=t.indexOf(c);if(i<0||c===-1||q==='low')return c;return u>=c/2?t[i+1]:c}`, hint: 'Check blockers first, then usage.' },
